for (int i = 0; i < cards.length; i++) {
    int smallest = i;
    for (int k = i + 1; k < cards.length; k++) {
        if (cards[k] < cards[smallest]) {
            smallest = k;
        }
    }
    // swap cards[i] and cards[smallest]
}

int temp = cards[0];
cards[0] = cards[3];
cards[3] = temp;

for (int i = 1; i < cards.length; i++) {
    int card = cards[i];
    int k = i - 1;
    while (k >= 0 && cards[k] > card) {
        cards[k + 1] = cards[k];
        k--;
    }
    cards[k + 1] = card;
}
